   "Uma cadência mais alta em uma marcha mais fácil é mais gentil com os joelhos do que pisar lentamente em uma marcha dura.",
   "Mantenha a parte superior do corpo relaxada e as costas longas, em vez de curvar ou balançar de um lado para o outro."
