   "Comece mais leve do que o peso de transporte de um braço por mão. Dois braços acima da cabeça não é duas vezes mais fácil, é o dobro para estabilizar.",
   "Tenha um plano para resgatar antes de começar e leve-o para onde possa largar os pesos com segurança.",
   "Distâncias curtas bem feitas superam as longas feitas dobradas. Pare a série quando suas costelas começarem a se dilatar, e não quando seus ombros cederem."
