   "Segure ambas as alças com uma pegada pronada e deixe os braços pendurados sobre os ombros.",
   "Reme os dois kettlebells para cima, afastando os cotovelos para os lados, longe das costelas, em vez de voltar ao longo delas.",
   "Pare quando os braços estiverem aproximadamente alinhados com os ombros e aperte as escápulas.",
   "Abaixe os kettlebells sob controle até que seus braços fiquem retos novamente e repita para as repetições desejadas."
