   "O pé que pisa faz a viagem; o pé da frente não se move. Se mudar entre as repetições, seu passo será muito longo ou muito curto.",
   "O rack remove o equilíbrio, não a carga - mantenha o tronco apoiado e levante-se do fundo, em vez de recostar-se na barra."
